import assert from 'node:assert/strict';
import { access, mkdtemp, readdir, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { resolve } from 'node:path';
import test from 'node:test';

import { buildHelpReferencePages } from './help-reference/build.ts';
import { replaceSiteNavigation } from './site-navigation-contract.ts';

const pages = resolve('docs/pages/sdlc-development');
const generated = ['glossary.html', 'roles.html'];
const marker =
  '<!-- GENERATED by npm run help:build (scripts/help-reference/). Do not edit by hand. -->';

await test('only the two generated reference pages carry the marker after the doctype', async () => {
  for (const name of generated) {
    const html = await readFile(resolve(pages, name), 'utf8');
    assert.deepEqual(html.split('\n').slice(0, 2), ['<!doctype html>', marker], name);
    assert.equal(html.split(marker).length, 2, name);
  }
  for (const name of ['intent-maturity-map.html', 'help-reference.css']) {
    assert.doesNotMatch(
      await readFile(resolve(pages, name), 'utf8'),
      /(?:<!--|\/\*)\s*GENERATED/iu,
      name,
    );
  }
});

await test('the generator reproduces both course files with their final navigation', async (t) => {
  const directory = await mkdtemp(resolve(tmpdir(), 'course-help-'));
  t.after(() => rm(directory, { recursive: true, force: true }));
  await buildHelpReferencePages(directory);
  assert.deepEqual((await readdir(directory)).sort(), generated);
  for (const name of generated) {
    const rebuilt = await readFile(resolve(directory, name));
    const html = rebuilt.toString('utf8');
    assert.equal(replaceSiteNavigation(html, { section: 'help' }), html, name);
    assert.deepEqual(rebuilt, await readFile(resolve(pages, name)), name);
  }
});

await test('the course source tree omits the retired environment pages, data and stylesheet', async () => {
  for (const name of [
    'environment-scales.html',
    'environment-contours.html',
    'environment-data.json',
    'environment.css',
  ])
    await assert.rejects(
      access(resolve('docs/pages/sdlc-development', name)),
      { code: 'ENOENT' },
      name,
    );
});
